package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ValueInstantiator.Vanilla;
import com.fasterxml.jackson.databind.deser.impl.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_constructValueInstantiator_TriageGen1Test {

    private DeserializationConfig config;
    private BeanDescription beanDesc;
    private JavaType javaType;
    private MapperConfig<?> mapperConfig;

    @Before
    public void setUp() {
        config = mock(DeserializationConfig.class);
        beanDesc = mock(BeanDescription.class);
        javaType = mock(JavaType.class);
        mapperConfig = mock(MapperConfig.class);

        when(beanDesc.getType()).thenReturn(javaType);
    }

    /**
     * Test Case 1: Standard Collection (List/ArrayList) with no non-default creator.
     * Should return Vanilla TYPE_COLLECTION.
     */
    @Test
    public void testConstructValueInstantiator_VanillaCollection() {
        when(javaType.getRawClass()).thenReturn(List.class);

        // Using reflection or a subclass if CreatorCollector is package-private/protected 
        // to simulate the internal state since we can't easily trigger _hasNonDefaultCreator via public API without creators
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        // Vanilla.TYPE_COLLECTION is a specific internal type
        // Based on code: return new Vanilla(Vanilla.TYPE_COLLECTION);
        // We check if it behaves like a Vanilla instantiator
        assertTrue(instantiator instanceof ValueInstantiator.Vanilla);
    }

    /**
     * Test Case 2: Standard Map (LinkedHashMap) with no non-default creator.
     * Should return Vanilla TYPE_MAP.
     */
    @Test
    public void testConstructValueInstantiator_VanillaMap() {
        when(javaType.getRawClass()).thenReturn(LinkedHashMap.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        assertTrue(instantiator instanceof ValueInstantiator.Vanilla);
    }

    /**
     * Test Case 3: Standard HashMap with no non-default creator.
     * Should return Vanilla TYPE_HASH_MAP.
     */
    @Test
    public void testConstructValueInstantiator_VanillaHashMap() {
        when(javaType.getRawClass()).thenReturn(HashMap.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        assertTrue(instantiator instanceof ValueInstantiator.Vanilla);
    }

    /**
     * Test Case 4: Complex Object (Non-standard)
     * Should return StdValueInstantiator.
     * We trigger this by adding a creator, which sets _hasNonDefaultCreator to true.
     */
    @Test
    public void testConstructValueInstantiator_StdValueInstantiator() {
        // A custom POJO class
        class MyBean {
            public MyBean() {}
        }
        when(javaType.getRawClass()).thenReturn(MyBean.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        // Adding a property creator triggers _hasNonDefaultCreator = true
        // We use a mock for AnnotatedWithParams
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        collector.addPropertyCreator(mockCreator, true, new SettableBeanProperty[0]);

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        // If _hasNonDefaultCreator is true, it bypasses Vanilla and creates StdValueInstantiator
        assertTrue(instantiator instanceof StdValueInstantiator);
    }

    /**
     * Test Case 5: Non-standard type (e.g. String) with no non-default creator.
     * Should fall through to StdValueInstantiator because it's not in the Vanilla list.
     */
    @Test
    public void testConstructValueInstantiator_FallthroughToStd() {
        when(javaType.getRawClass()).thenReturn(String.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        // Since no creators are added, _hasNonDefaultCreator is false.
        // But String.class is not in the if-else if block for Vanilla.
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        // It should reach the end of the method and return StdValueInstantiator
        assertTrue(instantiator instanceof StdValueInstantiator);
    }

    /**
     * Test Case 6: Testing various creator types to ensure configure methods are called.
     * This is implicitly covered by the StdValueInstantiator path in Test Case 4,
     * but we ensure the logic flow is exercised.
     */
    @Test
    public void testConstructValueInstantiator_AllCreatorsConfigured() {
        class MyBean { public MyBean() {} }
        when(javaType.getRawClass()).thenReturn(MyBean.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        // Add various creators to ensure _hasNonDefaultCreator becomes true
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        collector.setDefaultCreator(creator);
        collector.addStringCreator(creator);
        collector.addIntCreator(creator);
        collector.addLongCreator(creator);
        collector.addDoubleCreator(creator);
        collector.addBooleanCreator(creator);
        collector.addDelegatingCreator(creator, true, null);
        collector.addPropertyCreator(creator, true, null);

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        assertTrue(instantiator instanceof StdValueInstantiator);
    }
}
